// ⚙️ Configuración — los tokens de Meta viven SOLO acá
return [{ json: {
  BOT_SECRET: 'PEGAR_HORIZON_BOT_SECRET',
  WA_TOKEN: 'PEGAR_TOKEN_PERMANENTE_WHATSAPP',      // Meta → WhatsApp → Configuración de la API (usuario del sistema)
  WA_PHONE_ID: 'PEGAR_PHONE_NUMBER_ID',
  IG_TOKEN: 'PEGAR_TOKEN_INSTAGRAM',                 // Instagram API con inicio de sesión de Instagram
} }];

// Valida que la llamada venga de HORIZON (OPS o los otros flujos) y arma el envío
const cfg = $('Config').first().json;
const req = $('Enviar mensaje').first().json;
const auth = String(req.headers?.authorization || '');
if (auth !== 'Bearer ' + cfg.BOT_SECRET) throw new Error('No autorizado');
const { canal, contacto_id, texto } = req.body || {};
if (!canal || !contacto_id || !texto) throw new Error('Faltan datos');
if (canal === 'whatsapp') return [{ json: {
  url: 'https://graph.facebook.com/v21.0/' + cfg.WA_PHONE_ID + '/messages', token: cfg.WA_TOKEN,
  body: { messaging_product: 'whatsapp', to: contacto_id, type: 'text', text: { body: texto } } } }];
return [{ json: {
  url: 'https://graph.instagram.com/v21.0/me/messages', token: cfg.IG_TOKEN,
  body: { recipient: { id: contacto_id }, message: { text: texto } } } }];
